"""Validate credential-free evidence generated by the Lab 1 participant paths."""

from __future__ import annotations

import json
from typing import Any

_TOKEN_FIELDS = (
    "baseline_prompt_tokens",
    "memory_prompt_tokens",
    "retrieved_guideline_tokens",
    "estimated_request_tokens_with_memory",
    "repeated_prompt_reduction_tokens",
    "estimated_request_reduction_tokens",
)

_EVIDENCE_TYPES = {
    "local_algorithm_validation",
    "oci_sdk_execution_validation",
    "oci_sdk_inference_validation",
}


def _required_string(payload: dict[str, Any], name: str) -> str:
    """Return a required non-empty string from a participant evidence document."""

    value = payload.get(name)
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"Evidence field '{name}' must be a non-empty string")
    return value.strip()


def _string_list(payload: dict[str, Any], name: str) -> list[str]:
    """Return a list of non-empty strings or reject malformed evidence."""

    value = payload.get(name)
    valid_items = isinstance(value, list) and all(
        isinstance(item, str) and item.strip() for item in value
    )
    if not valid_items:
        raise ValueError(f"Evidence field '{name}' must be an array of non-empty strings")
    return [item.strip() for item in value]


def _sdk_execution(payload: dict[str, Any]) -> dict[str, object] | None:
    """Validate the additional, non-secret facts emitted by the direct SDK path."""

    if payload["evidence_type"] not in {
        "oci_sdk_execution_validation",
        "oci_sdk_inference_validation",
    }:
        return None
    execution = payload.get("sdk_execution")
    if not isinstance(execution, dict):
        raise ValueError("SDK evidence field 'sdk_execution' must be an object")
    if execution.get("schema_policy") != "REQUIRE_EXISTING":
        raise ValueError("SDK evidence must use SchemaPolicy.REQUIRE_EXISTING")
    if execution.get("search_strategy") != "KEYWORD":
        raise ValueError("SDK evidence must use keyword search for Lab 1")
    if execution.get("persistence_confirmed") is not True:
        raise ValueError("SDK evidence does not confirm durable retrieval")

    safe_execution: dict[str, object] = {}
    for field in ("individual_scope", "team_shared_scope", "control_scope"):
        safe_execution[field] = _required_string(execution, field)
    for field in (
        "individual_created",
        "individual_existing",
        "team_shared_created",
        "team_shared_existing",
        "team_shared_result_count",
    ):
        value = execution.get(field)
        if not isinstance(value, int) or value < 0:
            raise ValueError(f"SDK execution field '{field}' must be a non-negative integer")
        safe_execution[field] = value
    safe_execution["schema_policy"] = "REQUIRE_EXISTING"
    safe_execution["search_strategy"] = "KEYWORD"
    safe_execution["persistence_confirmed"] = True
    return safe_execution


def _positive_int(payload: dict[str, Any], name: str) -> int:
    value = payload.get(name)
    if not isinstance(value, int) or value < 0:
        raise ValueError(f"Inference field '{name}' must be a non-negative integer")
    return value


def _inference(payload: dict[str, Any]) -> dict[str, object] | None:
    """Validate real OCI Inference usage before the UI presents it as token evidence."""

    if payload["evidence_type"] != "oci_sdk_inference_validation":
        return None
    inference = payload.get("inference")
    if not isinstance(inference, dict):
        raise ValueError("Inference evidence field 'inference' must be an object")
    if inference.get("measurement_type") != "oci_inference_usage":
        raise ValueError("Inference evidence must contain OCI provider usage")
    if inference.get("both_quality_checks_passed") is not True:
        raise ValueError("Inference evidence must confirm response quality")
    baseline = inference.get("baseline")
    optimized = inference.get("memory_optimized")
    if not isinstance(baseline, dict) or not isinstance(optimized, dict):
        raise ValueError("Inference evidence must contain both prompt variants")
    safe_variants: dict[str, dict[str, object]] = {}
    for label, variant in (("baseline", baseline), ("memory_optimized", optimized)):
        if variant.get("quality_passed") is not True:
            raise ValueError(f"Inference {label} did not satisfy quality checks")
        if variant.get("finish_reason") != "COMPLETE":
            raise ValueError(f"Inference {label} was not complete")
        prompt_tokens = _positive_int(variant, "prompt_tokens")
        completion_tokens = _positive_int(variant, "completion_tokens")
        total_tokens = _positive_int(variant, "total_tokens")
        if total_tokens != prompt_tokens + completion_tokens:
            raise ValueError(f"Inference {label} usage is inconsistent")
        safe_variants[label] = {
            "prompt_tokens": prompt_tokens,
            "completion_tokens": completion_tokens,
            "total_tokens": total_tokens,
            "latency_ms": _positive_int(variant, "latency_ms"),
            "quality_passed": True,
            "finish_reason": "COMPLETE",
        }
    reduction = _positive_int(inference, "input_token_reduction")
    baseline_tokens = safe_variants["baseline"]["prompt_tokens"]
    optimized_tokens = safe_variants["memory_optimized"]["prompt_tokens"]
    if not isinstance(baseline_tokens, int) or not isinstance(optimized_tokens, int):
        raise ValueError("Inference token evidence is malformed")
    if optimized_tokens >= baseline_tokens or reduction != baseline_tokens - optimized_tokens:
        raise ValueError("Retrieved memory did not reduce provider prompt tokens")
    percent = _positive_int(inference, "input_token_reduction_percent")
    return {
        "measurement_type": "oci_inference_usage",
        "model_id": _required_string(inference, "model_id"),
        "max_output_tokens": _positive_int(inference, "max_output_tokens"),
        "baseline": safe_variants["baseline"],
        "memory_optimized": safe_variants["memory_optimized"],
        "input_token_reduction": reduction,
        "input_token_reduction_percent": percent,
        "both_quality_checks_passed": True,
    }


def load_participant_evidence(raw_json: str) -> dict[str, object]:
    """Load only the safe, explicit schemas emitted by the participant runners.

    The UI deliberately rejects arbitrary JSON. It accepts identifiers, a query,
    Boolean isolation evidence, and only validates provider token usage when the
    participant ran the real OCI Inference comparison.
    """

    try:
        payload = json.loads(raw_json)
    except json.JSONDecodeError as error:
        raise ValueError("The participant evidence is not valid JSON") from error
    if not isinstance(payload, dict):
        raise ValueError("The participant evidence root must be a JSON object")
    if payload.get("evidence_type") not in _EVIDENCE_TYPES:
        raise ValueError("The JSON is not approved Lab 1 participant evidence")
    if payload.get("contains_no_secrets") is not True:
        raise ValueError("The evidence must explicitly declare contains_no_secrets=true")
    if payload.get("isolation_passed") is not True:
        raise ValueError("The evidence does not show an approved isolation result")

    algorithm = payload.get("algorithm")
    if not isinstance(algorithm, dict):
        raise ValueError("Evidence field 'algorithm' must be an object")
    query = _required_string(algorithm, "query")
    scope = _required_string(algorithm, "scope")
    max_results = algorithm.get("max_results")
    if not isinstance(max_results, int) or max_results < 0:
        raise ValueError("Algorithm field 'max_results' must be a non-negative integer")

    comparison = payload.get("prompt_comparison")
    if not isinstance(comparison, dict):
        raise ValueError("Evidence field 'prompt_comparison' must be an object")
    safe_comparison: dict[str, int] = {}
    for field in _TOKEN_FIELDS:
        value = comparison.get(field)
        if not isinstance(value, int) or value < 0:
            raise ValueError(f"Prompt comparison field '{field}' must be a non-negative integer")
        safe_comparison[field] = value

    retrieved = _string_list(payload, "retrieved_procedure_ids")
    cross_team = _string_list(payload, "cross_team_visible_procedure_ids")
    if cross_team:
        raise ValueError("Approved isolation evidence cannot contain cross-team procedures")

    evidence_type = payload["evidence_type"]
    safe_algorithm: dict[str, object] = {
        "scope": scope,
        "query": query,
        "max_results": max_results,
    }
    persisted: list[str] | None = None
    if evidence_type in {"oci_sdk_execution_validation", "oci_sdk_inference_validation"}:
        record_types = algorithm.get("record_types")
        if record_types != ["guideline"]:
            raise ValueError("SDK evidence must retrieve procedural guideline records")
        if not retrieved:
            raise ValueError("SDK evidence must retrieve at least one procedural guideline")
        persisted = _string_list(payload, "persisted_procedure_ids")
        if not persisted:
            raise ValueError("SDK evidence must identify persisted procedures")
        safe_algorithm["record_types"] = ["guideline"]
    safe_evidence: dict[str, object] = {
        "active_team_id": _required_string(payload, "active_team_id"),
        "active_team_name": _required_string(payload, "active_team_name"),
        "algorithm": safe_algorithm,
        "retrieved_procedure_ids": retrieved,
        "cross_team_challenge": _required_string(payload, "cross_team_challenge"),
        "cross_team_visible_procedure_ids": cross_team,
        "isolation_passed": True,
        "prompt_comparison": safe_comparison,
        "evidence_type": evidence_type,
        "contains_no_secrets": True,
    }
    exercise_mode = payload.get("exercise_mode")
    if exercise_mode is not None:
        if exercise_mode != "memory_only":
            raise ValueError("Evidence field 'exercise_mode' is not approved")
        safe_evidence["exercise_mode"] = exercise_mode
        selected = _required_string(payload, "selected_procedure_id")
        safe_evidence["selected_procedure_id"] = selected
    sdk_execution = _sdk_execution(payload)
    if sdk_execution is not None:
        safe_evidence["sdk_execution"] = sdk_execution
        safe_evidence["persisted_procedure_ids"] = persisted
    inference = _inference(payload)
    if inference is not None:
        safe_evidence["inference"] = inference
    return safe_evidence
